-- Emerald 24/7 Grocery - database matching Emerald_Data_Dictionaryt.xlsx (14 tables)
-- Import via phpMyAdmin (XAMPP). Default password for all seeded users/customers: password
SET FOREIGN_KEY_CHECKS = 0;
DROP DATABASE IF EXISTS emerald_247_current;
CREATE DATABASE emerald_247_current CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE emerald_247_current;
SET NAMES utf8mb4;

CREATE TABLE categories (
  category_id int(11) NOT NULL AUTO_INCREMENT,
  category_name varchar(100) NOT NULL,
  description varchar(255) DEFAULT NULL,
  status enum('Active','Inactive') NOT NULL DEFAULT 'Active',
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (category_id)
) ENGINE=InnoDB;

CREATE TABLE users (
  user_id int(11) NOT NULL AUTO_INCREMENT,
  full_name varchar(150) NOT NULL,
  email varchar(100) NOT NULL,
  password varchar(255) NOT NULL,
  role enum('Admin','Staff','Customer') NOT NULL DEFAULT 'Staff',
  contact_number varchar(50) DEFAULT NULL,
  address varchar(255) DEFAULT NULL,
  status enum('Active','Inactive') NOT NULL DEFAULT 'Active',
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id),
  UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB;

CREATE TABLE customers (
  customer_id int(11) NOT NULL AUTO_INCREMENT,
  full_name varchar(150) NOT NULL,
  email varchar(100) NOT NULL,
  password varchar(255) NOT NULL,
  contact_number varchar(50) DEFAULT NULL,
  address varchar(255) DEFAULT NULL,
  status enum('Active','Inactive') NOT NULL DEFAULT 'Active',
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (customer_id),
  UNIQUE KEY uq_customers_email (email)
) ENGINE=InnoDB;

CREATE TABLE suppliers (
  supplier_id int(11) NOT NULL AUTO_INCREMENT,
  supplier_name varchar(150) NOT NULL,
  contact_person varchar(100) DEFAULT NULL,
  contact_number varchar(50) DEFAULT NULL,
  email varchar(100) DEFAULT NULL,
  address varchar(255) DEFAULT NULL,
  status enum('Active','Inactive') NOT NULL DEFAULT 'Active',
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (supplier_id)
) ENGINE=InnoDB;

CREATE TABLE products (
  product_id int(11) NOT NULL AUTO_INCREMENT,
  category_id int(11) NOT NULL,
  product_name varchar(150) NOT NULL,
  description varchar(255) DEFAULT NULL,
  price decimal(10,2) NOT NULL,
  stock_qty int(11) NOT NULL DEFAULT 0,
  reorder_level int(11) NOT NULL DEFAULT 10,
  unit varchar(50) NOT NULL DEFAULT 'piece',
  image varchar(255) DEFAULT NULL,
  status enum('Active','Inactive') NOT NULL DEFAULT 'Active',
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (product_id),
  KEY idx_products_category (category_id),
  CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories (category_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE inventory (
  inventory_id int(11) NOT NULL AUTO_INCREMENT,
  product_id int(11) NOT NULL,
  quantity int(11) NOT NULL DEFAULT 0,
  reorder_level int(11) NOT NULL DEFAULT 10,
  last_updated datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (inventory_id),
  KEY idx_inventory_product (product_id),
  CONSTRAINT fk_inventory_product FOREIGN KEY (product_id) REFERENCES products (product_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE inventory_transactions (
  inventory_transaction_id int(11) NOT NULL AUTO_INCREMENT,
  product_id int(11) NOT NULL,
  transaction_type enum('IN','OUT','ADJUST') NOT NULL,
  quantity int(11) NOT NULL,
  reference varchar(100) DEFAULT NULL,
  remarks varchar(255) DEFAULT NULL,
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by int(11) NOT NULL,
  PRIMARY KEY (inventory_transaction_id),
  KEY idx_it_product (product_id),
  KEY idx_it_user (created_by),
  CONSTRAINT fk_it_product FOREIGN KEY (product_id) REFERENCES products (product_id) ON UPDATE CASCADE,
  CONSTRAINT fk_it_user FOREIGN KEY (created_by) REFERENCES users (user_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE orders (
  order_id int(11) NOT NULL AUTO_INCREMENT,
  customer_id int(11) NOT NULL,
  order_date datetime NOT NULL,
  order_status enum('Pending','Processing','Ready','Delivered','Cancelled') NOT NULL DEFAULT 'Pending',
  payment_method enum('Cash','GCash') NOT NULL,
  total_amount decimal(10,2) NOT NULL,
  delivery_address varchar(255) DEFAULT NULL,
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (order_id),
  KEY idx_orders_customer (customer_id),
  CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id) REFERENCES customers (customer_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE order_items (
  order_item_id int(11) NOT NULL AUTO_INCREMENT,
  order_id int(11) NOT NULL,
  product_id int(11) NOT NULL,
  quantity int(11) NOT NULL,
  unit_price decimal(10,2) NOT NULL,
  total_price decimal(10,2) NOT NULL,
  PRIMARY KEY (order_item_id),
  KEY idx_oi_order (order_id),
  KEY idx_oi_product (product_id),
  CONSTRAINT fk_oi_order FOREIGN KEY (order_id) REFERENCES orders (order_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_oi_product FOREIGN KEY (product_id) REFERENCES products (product_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE sales (
  sale_id int(11) NOT NULL AUTO_INCREMENT,
  user_id int(11) NOT NULL,
  customer_id int(11) DEFAULT NULL,
  sale_date datetime NOT NULL,
  payment_method enum('Cash','GCash') NOT NULL,
  total_amount decimal(10,2) NOT NULL,
  status enum('Completed','Cancelled','Pending') NOT NULL DEFAULT 'Completed',
  PRIMARY KEY (sale_id),
  KEY idx_sales_user (user_id),
  KEY idx_sales_customer (customer_id),
  CONSTRAINT fk_sales_user FOREIGN KEY (user_id) REFERENCES users (user_id) ON UPDATE CASCADE,
  CONSTRAINT fk_sales_customer FOREIGN KEY (customer_id) REFERENCES customers (customer_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE sale_items (
  sale_item_id int(11) NOT NULL AUTO_INCREMENT,
  sale_id int(11) NOT NULL,
  product_id int(11) NOT NULL,
  quantity int(11) NOT NULL,
  unit_price decimal(10,2) NOT NULL,
  total_price decimal(10,2) NOT NULL,
  PRIMARY KEY (sale_item_id),
  KEY idx_si_sale (sale_id),
  KEY idx_si_product (product_id),
  CONSTRAINT fk_si_sale FOREIGN KEY (sale_id) REFERENCES sales (sale_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_si_product FOREIGN KEY (product_id) REFERENCES products (product_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE purchase_orders (
  po_id int(11) NOT NULL AUTO_INCREMENT,
  supplier_id int(11) NOT NULL,
  po_date date NOT NULL,
  expected_date date DEFAULT NULL,
  status enum('Pending','Received','Cancelled') NOT NULL DEFAULT 'Pending',
  total_amount decimal(10,2) NOT NULL,
  created_by int(11) NOT NULL,
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (po_id),
  KEY idx_po_supplier (supplier_id),
  KEY idx_po_user (created_by),
  CONSTRAINT fk_po_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers (supplier_id) ON UPDATE CASCADE,
  CONSTRAINT fk_po_user FOREIGN KEY (created_by) REFERENCES users (user_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE purchase_order_items (
  po_item_id int(11) NOT NULL AUTO_INCREMENT,
  po_id int(11) NOT NULL,
  product_id int(11) NOT NULL,
  quantity int(11) NOT NULL,
  unit_cost decimal(10,2) NOT NULL,
  total_cost decimal(10,2) NOT NULL,
  PRIMARY KEY (po_item_id),
  KEY idx_poi_po (po_id),
  KEY idx_poi_product (product_id),
  CONSTRAINT fk_poi_po FOREIGN KEY (po_id) REFERENCES purchase_orders (po_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_poi_product FOREIGN KEY (product_id) REFERENCES products (product_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE payments (
  payment_id int(11) NOT NULL AUTO_INCREMENT,
  reference_type enum('SALE','ORDER') NOT NULL,
  reference_id int(11) NOT NULL,
  payment_method enum('Cash','GCash') NOT NULL,
  amount decimal(10,2) NOT NULL,
  payment_date datetime NOT NULL,
  status enum('Pending','Completed','Failed') NOT NULL DEFAULT 'Pending',
  reference_number varchar(100) DEFAULT NULL,
  created_at datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (payment_id),
  KEY idx_pay_ref (reference_type, reference_id)
) ENGINE=InnoDB;


